/* Registered developer entries. Importing this registry performs no browser operations. */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.TarotDevCheckpoints = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";
  const allEvents = Object.freeze(["alenon_prologue", "landing_devil_memory", "garden_shiopon_meet", "garden_lumiere_gate"]);
  const definitions = {};

  function register(id, definition) {
    definitions[id] = Object.freeze({ id, ...definition });
  }

  const alenonScenarios = [
    ["intro-incomplete", "intro", [], "not_joined"],
    ["intro-complete", "intro", ["alenon_prologue"], "not_joined"],
    ["pad-return", "pad_return", ["alenon_prologue"], "not_joined"],
    ["pad-return-waiting", "pad_return", allEvents, "waiting_at_landing"],
  ];
  for (const [suffix, spawnId, events, companion] of alenonScenarios) {
    const id = "alenon-resume-" + suffix;
    const fixture = Object.freeze({ version: 1, checkpoint: Object.freeze({mapId: "alenon", spawnId}),
      completedEvents: Object.freeze([...events]), companion });
    register(id, { event: "alenon-resume", segment: "alenon-resume-entry", map: "alenon",
      spawn: spawnId, temporaryState: fixture, requiredRuntime: Object.freeze(["alenon.html", "progress.js", "progress-resume.js", "alenon-resume.js"]),
      entryAction: "registered ?dev=" + id, emittedSignal: "tarot-breaker:alenon-resume-ready",
      receivingRuntime: "real Alenon strict Continue boot", expectedFirstRuntimeState: "locked until decoded assets, valid collision and authored safe ground spawn",
      durableWritePolicy: "production writes forbidden; checkpoint-specific dev session only at authored prologue completion" });
  }

  for (const [suffix, spawnId, events, companion] of alenonScenarios) {
    const id = "public-continue-alenon-" + suffix;
    register(id, {event:"public-continue", segment:"public-continue-alenon", map:"alenon", spawn:spawnId,
      temporaryState:Object.freeze({version:1, checkpoint:Object.freeze({mapId:"alenon", spawnId}), completedEvents:Object.freeze([...events]), companion}),
      requiredRuntime:Object.freeze(["alenon.html", "public-continue.js", "alenon-public-continue.js", "progress.js", "progress-resume.js", "alenon-resume.js"]),
      entryAction:"registered ?dev=" + id, emittedSignal:"tarot-breaker:alenon-resume-ready",
      receivingRuntime:"real Alenon Public adapter with injected session-only Progress backend",
      expectedFirstRuntimeState:"locked until decoded assets, valid collision and authored safe ground spawn",
      durableWritePolicy:"production writes forbidden; injected checkpoint-specific session backend; cross-map departure contained"});
  }

  const landingScenarios = [
    ["landing-resume-arrival", ["alenon_prologue"], "not_joined"],
    ["landing-resume-memory-complete", ["alenon_prologue", "landing_devil_memory"], "not_joined"],
    ["landing-resume-waiting", ["alenon_prologue", "landing_devil_memory", "garden_shiopon_meet"], "waiting_at_landing"],
  ];
  for (const [id, events, companion] of landingScenarios) {
    const fixture = Object.freeze({ version: 1,
      checkpoint: Object.freeze({mapId: "star_country_landing", spawnId: "pad_ground"}),
      completedEvents: Object.freeze([...events]), companion });
    register(id, { event: "garden-landing-continue-recovery", segment: "landing-resume-entry", map: "star_country_landing",
      spawn: "pad_ground", temporaryState: fixture,
      requiredRuntime: Object.freeze(["star-country-landing.html", "progress.js", "progress-resume.js", "landing-resume.js"]),
      entryAction: "registered ?dev=" + id, emittedSignal: "tarot-breaker:landing-resume-ready",
      receivingRuntime: "real Landing strict Continue boot",
      expectedFirstRuntimeState: "locked until decoded assets, strict collision and authored pad_ground spawn",
      durableWritePolicy: "production writes forbidden; checkpoint-specific dev session only at authored event completion" });
  }

  const gardenScenarios = [
    ["garden-resume-before-shiopon", ["alenon_prologue", "landing_devil_memory"], "not_joined"],
    ["garden-resume-after-shiopon", ["alenon_prologue", "landing_devil_memory", "garden_shiopon_meet"], "joined_with_shion"],
    ["garden-resume-after-lumiere", allEvents, "joined_with_shion"],
  ];
  for (const [id, events, companion] of gardenScenarios) {
    const fixture = Object.freeze({ version: 1,
      checkpoint: Object.freeze({mapId: "star_gate_garden", spawnId: "south_gate"}),
      completedEvents: Object.freeze([...events]), companion });
    register(id, { event: "garden-landing-continue-recovery", segment: "garden-resume-entry", map: "star_gate_garden",
      spawn: "south_gate", temporaryState: fixture,
      requiredRuntime: Object.freeze(["index.html", "progress.js", "progress-resume.js", "garden-resume.js"]),
      entryAction: "registered ?dev=" + id, emittedSignal: "tarot-breaker:garden-resume-ready",
      receivingRuntime: "real Garden strict Continue boot",
      expectedFirstRuntimeState: "locked until decoded assets, strict collision and authored south_gate spawn",
      durableWritePolicy: "production writes forbidden; checkpoint-specific dev session only at authored event completion" });
  }

  Object.freeze(definitions);
  function get(id) { return Object.prototype.hasOwnProperty.call(definitions, id) ? definitions[id] : null; }
  function list() { return Object.values(definitions); }
  function isDevRequest(search) { return new URLSearchParams(search || "").has("dev"); }
  function resolve(search) { return get(new URLSearchParams(search || "").get("dev")); }
  return Object.freeze({definitions, get, list, resolve, isDevRequest});
});

garden-progress-observer.js:
/* Phase 2A-4c observer + Phase 2A-5c isolated Landing Continue transit.
 * Durable Progress is authoritative. Normal Landing -> Garden arrival also
 * refreshes the legacy session Journey projection so authored dialogue cannot
 * replay a completion that already exists in Progress.
 */
(function (root) {
  "use strict";

  const core = root.TarotProgressCore;
  if (!core) return;

  const params = new URLSearchParams(root.location.search);
  const landingResumeDev = params.get("from") === "landing" &&
    /^landing-resume-(arrival|memory-complete|waiting)$/.test(params.get("dev") || "");
  const gardenResumeDev = !params.has("from") &&
    /^garden-resume-(before-shiopon|after-shiopon|after-lumiere)$/.test(params.get("dev") || "");
  const gardenResumePublic = params.getAll("entry").length === 1 && params.get("entry") === "continue" &&
    !params.has("from") && !params.has("dev");

  let progress;
  if (gardenResumePublic) {
    const transit = root.TarotGardenContinueTransit;
    if (!transit?.ok || !transit.progress) {
      root.TarotGardenContinueTransit = Object.freeze({ok:false, reason:transit?.reason || "garden-public-transit-unavailable"});
      return;
    }
    progress = transit.progress;
  } else if (landingResumeDev || gardenResumeDev) {
    const transit = gardenResumeDev ? root.TarotGardenResume?.createSession({
      search: root.location.search,
      storage: root.sessionStorage,
    }) : root.TarotLandingResume?.createGardenTransitSession({
      search: root.location.search,
      storage: root.sessionStorage,
    });
    if (!transit?.ok) {
      root.TarotGardenDevTransit = Object.freeze({ok:false, reason:transit?.reason || "garden-transit-unavailable"});
      return;
    }
    root.TarotGardenDevTransit = transit;
    progress = transit.progress;
  } else {
    progress = core.createProgress();
    const loaded = progress.load();
    if (loaded.status !== "valid") return;
  }

  function note(message, error) {
    if (typeof console !== "undefined") console.warn("[Garden Progress]", message, error || "");
  }

  function syncJourneyFromProgress() {
    const current = progress.getCurrentState?.();
    const state = current?.state;
    if (!state || !Array.isArray(state.completedEvents) || !root.TarotJourney?.set) return;
    const has = id => state.completedEvents.includes(id);
    const joined = state.companion === "joined_with_shion";
    root.TarotJourney.set("landingMemoryDone", has("landing_devil_memory"));
    root.TarotJourney.set("gardenStory", {
      shioponDone: has("garden_shiopon_meet"),
      lumiereDone: has("garden_lumiere_gate"),
      joined,
    });
    root.TarotJourney.set("companion", joined ? { mode: "following" } : null);
  }

  // Garden only acknowledges that the unchanged URL arrival actually reached this scene.
  if (!landingResumeDev && params.get("from") === "landing") {
    try {
      progress.commitArrival({
        sourceMapId: "star_country_landing",
        destinationMapId: "star_gate_garden",
        spawnId: "south_gate",
        reason: "gate_to_garden",
      });
      syncJourneyFromProgress();
    } catch (error) {
      note("arrival observation was not persisted", error);
    }
  }

  root.addEventListener("tarot-breaker:interaction-end", function () {
    const state = root.TarotGardenDialogue?.getState?.() || root.TarotDialogue?.getState?.();
    if (!state) return;

    if (state.shioponDone === true && !progress.isEventCompleted("garden_shiopon_meet")) {
      try {
        progress.completeEvent("garden_shiopon_meet", {
          mapId: "star_gate_garden",
          spawnId: "south_gate",
        });
      } catch (error) {
        note("Shiopon meeting observation was not persisted", error);
      }
    }

    if (state.lumiereDone === true && !progress.isEventCompleted("garden_lumiere_gate")) {
      try {
        progress.completeEvent("garden_lumiere_gate", {
          mapId: "star_gate_garden",
          spawnId: "south_gate",
        });
      } catch (error) {
        note("Lumiere gate observation was not persisted", error);
      }
    }
  });
})(typeof globalThis !== "undefined" ? globalThis : window);

shared-dialogue.js:
(() => {
  "use strict";

  if (window.TarotDialogueUI) return;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function buildChars(textEl, text) {
    textEl.replaceChildren();
    const fragment = document.createDocumentFragment();
    const nodes = [];

    for (const ch of [...text]) {
      const span = document.createElement("span");
      span.className = "tb-dialogue-char";
      span.textContent = ch === " " ? "\u00a0" : ch;
      fragment.appendChild(span);
      nodes.push(span);
    }

    textEl.appendChild(fragment);
    return nodes;
  }

  function pauseFor(ch) {
    if (/[。！？!?]/.test(ch)) return 120;
    if (/[、，,…]/.test(ch)) return 72;
    return 34;
  }

  function createElements(mount, ids = {}) {
    const layer = document.createElement("section");
    layer.id = ids.layer || "dialogue-layer";
    layer.className = "tb-dialogue-layer";
    layer.hidden = true;
    layer.dataset.state = "idle";
    layer.setAttribute("aria-live", "polite");

    const button = document.createElement("button");
    button.id = ids.advance || "dialogue-advance";
    button.className = "tb-dialogue-window";
    button.type = "button";
    button.setAttribute("aria-label", "会話を進める");

    const speaker = document.createElement("span");
    speaker.id = ids.speaker || "dialogue-speaker";
    speaker.className = "tb-dialogue-speaker";

    const text = document.createElement("span");
    text.id = ids.text || "dialogue-text";
    text.className = "tb-dialogue-text";

    const next = document.createElement("span");
    next.className = "tb-dialogue-next";
    next.setAttribute("aria-hidden", "true");
    next.textContent = "▼";

    button.append(speaker, text, next);
    layer.appendChild(button);
    mount.appendChild(layer);

    return { layer, button, speaker, text, next };
  }

  function bindElements({ layer, button, speaker, text, next }) {
    if (!layer || !button || !speaker || !text || !next) {
      throw new Error("TarotDialogueUI: required dialogue elements are missing");
    }

    layer.classList.add("tb-dialogue-layer");
    button.classList.add("tb-dialogue-window");
    speaker.classList.add("tb-dialogue-speaker");
    text.classList.add("tb-dialogue-text");
    next.classList.add("tb-dialogue-next");

    return { layer, button, speaker, text, next };
  }

  function makeController(elements, options = {}) {
    const { layer, button, speaker, text, next } = elements;
    let chars = [];
    let token = 0;
    let complete = false;
    let active = false;
    let destroyed = false;
    let advanceHandler =
      typeof options.onAdvance === "function" ? options.onAdvance : null;

    function revealAll() {
      token += 1;
      for (const node of chars) node.classList.add("revealed");
      complete = true;
      next.classList.add("visible");
      layer.dataset.state = "dialogue";
      return true;
    }

    async function typeLine(fullText, currentToken) {
      const source = [...fullText];
      const instant =
        window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;

      if (instant) {
        revealAll();
        return;
      }

      for (let i = 0; i < source.length; i += 1) {
        if (destroyed || !active || currentToken !== token || complete) return;
        chars[i]?.classList.add("revealed");
        await sleep(pauseFor(source[i]));
      }

      if (destroyed || !active || currentToken !== token) return;
      for (const node of chars) node.classList.add("revealed");
      complete = true;
      next.classList.add("visible");
      layer.dataset.state = "dialogue";
    }

    function show({ speaker: speakerName = "", text: fullText = "", actor = "" } = {}) {
      token += 1;
      active = true;
      complete = false;
      speaker.textContent = speakerName;
      chars = buildChars(text, String(fullText));
      next.classList.remove("visible");
      layer.dataset.state = "dialogue";
      layer.dataset.speaker = speakerName;
      layer.dataset.actor = actor || "";
      layer.hidden = false;

      const currentToken = token;
      requestAnimationFrame(() => {
        if (!active || destroyed || currentToken !== token) return;
        layer.classList.add("visible");
        button.classList.add("visible");
      });

      typeLine(String(fullText), currentToken);
      return currentToken;
    }

    function hide() {
      token += 1;
      active = false;
      complete = false;
      chars = [];
      next.classList.remove("visible");
      layer.classList.remove("visible");
      button.classList.remove("visible");
      layer.dataset.state = "idle";
      layer.hidden = true;
    }

    function setState(state = "dialogue") {
      layer.dataset.state = state;
      button.setAttribute("aria-label", state === "acting" ? "会話演出を早送りする" : "会話を進める");
      if (state === "acting") next.classList.remove("visible");
    }

    function setAdvanceHandler(handler) {
      advanceHandler = typeof handler === "function" ? handler : null;
    }

    function handleAdvance(event) {
      if (!active) return false;
      if (event) {
        event.preventDefault?.();
        event.stopPropagation?.();
      }

      if (!complete) {
        revealAll();
        return true;
      }

      next.classList.remove("visible");
      advanceHandler?.();
      return true;
    }

    function onPointer(event) {
      handleAdvance(event);
    }

    function onKey(event) {
      if (!active) return;
      if (!["Enter", " ", "Spacebar"].includes(event.key)) return;
      handleAdvance(event);
    }

    button.addEventListener("click", onPointer);
    window.addEventListener("keydown", onKey, { passive: false });

    return Object.freeze({
      show,
      hide,
      revealAll,
      handleAdvance,
      setState,
      setAdvanceHandler,
      isActive: () => active,
      isComplete: () => complete,
      isTyping: () => active && !complete,
      elements: Object.freeze({ layer, button, speaker, text, next }),
      destroy() {
        destroyed = true;
        token += 1;
        button.removeEventListener("click", onPointer);
        window.removeEventListener("keydown", onKey);
      },
    });
  }

  function create(options = {}) {
    const mount = options.mount || document.body;
    const elements = createElements(mount, options.ids || {});
    return makeController(elements, options);
  }

  function bind(options = {}) {
    const elements = bindElements({
      layer: options.layer,
      button: options.button || options.layer,
      speaker: options.speaker,
      text: options.text,
      next: options.next,
    });
    return makeController(elements, options);
  }

  window.TarotDialogueUI = Object.freeze({
    version: "1.1.0",
    create,
    bind,
  });
})();

scene-preview41-fix.js:
(function (root) {
  "use strict";
  const layout = root.TarotSceneLayout;
  if (!layout) return;

  if (!document.querySelector('link[data-gate-polish="v2"]')) {
    const gatePolish = document.createElement("link");
    gatePolish.rel = "stylesheet";
    gatePolish.href = "./gate-polish.css?v=20260916-gate-polish-v2";
    gatePolish.dataset.gatePolish = "v2";
    document.head.appendChild(gatePolish);
  }

  const REFERENCE = layout.referenceSize;
  const STAIR_TOP_Y = layout.gate?.baseline ?? 242;
  const GATE_CENTER_X = layout.gate?.openingX ?? 800;
  const GATE_LIFT = 32;

  // The approved foreground is authored at the same 1448x1086 reference size
  // as the game map. Draw it 1:1. Do not rescale or re-center it.
  const previousForegroundOffset = {
    x: layout.foregroundOffset?.x || 0,
    y: layout.foregroundOffset?.y || 0,
  };
  const correctionX = -previousForegroundOffset.x;
  const correctionY = -previousForegroundOffset.y;

  function shiftPoints(points, dx, dy) {
    return (points || []).map(([x, y]) => [x + dx, y + dy]);
  }
  function shiftShape(shape, dx, dy) {
    if (!shape) return shape;
    if (shape.type === "ellipse") {
      return { ...shape, cx: shape.cx + dx, cy: shape.cy + dy };
    }
    return { ...shape, points: shiftPoints(shape.points, dx, dy) };
  }

  // scene-layout.js still defines the older -15px foreground offset. Move only
  // its foreground-derived depth/collision helpers back to the zero-origin.
  for (const area of layout.occluders || []) {
    if (area.source !== "foreground") continue;
    if (Array.isArray(area.bounds)) area.bounds[0] += correctionX;
    area.baseline += correctionY;
    area.footArea = shiftShape(area.footArea, correctionX, correctionY);
    area.points = shiftPoints(area.points, correctionX, correctionY);
  }

  const oldForegroundSolidCenters = new Set(["569,452", "1010,452", "227,438", "1223,528"]);
  for (const shape of layout.solidBases || []) {
    if (shape.type !== "ellipse") continue;
    if (oldForegroundSolidCenters.has(`${shape.cx},${shape.cy}`)) {
      shape.cx += correctionX;
      shape.cy += correctionY;
    }
  }

  layout.foregroundOffset = Object.freeze({ x: 0, y: 0 });
  layout.paintForeground = function paintForeground(ctx, foreground) {
    const w = REFERENCE.width;
    const h = REFERENCE.height;
    ctx.clearRect(0, 0, w, h);
    ctx.drawImage(foreground, 0, 0, w, h);
    layout.latestForegroundPlacement = Object.freeze({
      sourceW: foreground.naturalWidth || w,
      sourceH: foreground.naturalHeight || h,
      drawX: 0,
      drawY: 0,
      drawW: w,
      drawH: h,
      mode: "native-reference-1to1",
    });
  };

  // Preserve the cleaned map/background pipeline underneath the transparent
  // foreground so transparent openings reveal the world rather than a cover.
  layout.paintBackground = function paintBackground(ctx, background, sky) {
    const w = REFERENCE.width;
    const h = REFERENCE.height;
    const sourceW = background.naturalWidth || w;
    const sourceH = background.naturalHeight || h;
    const scale = Math.min(w / sourceW, h / sourceH);
    const drawW = sourceW * scale;
    const drawH = sourceH * scale;
    const drawX = (w - drawW) / 2;
    ctx.clearRect(0, 0, w, h);
    ctx.drawImage(background, drawX, 0, drawW, drawH);

    if (!sky || !Array.isArray(layout.legacyGate) || !layout.legacyGate.length) return;
    const fill = ctx.createLinearGradient(0, 0, 0, 290);
    fill.addColorStop(0, "#263b76");
    fill.addColorStop(1, "#9b95ce");
    for (let band = 16; band >= 0; band -= 2) {
      const points = layout.legacyGate.map(([x, y]) => [
        800 + (x - 800) * (1 + band / 175),
        140 + (y - 140) * (1 + band / 175),
      ]);
      ctx.save();
      layout.trace(ctx, points);
      ctx.clip();
      ctx.globalAlpha = band === 0 ? 1 : 0.2;
      ctx.fillStyle = fill;
      ctx.fillRect(0, 0, w, h);
      ctx.drawImage(sky, 0, 0, w, h);
      ctx.restore();
    }
  };

  // Gate and inner light share one centre axis and stay 32px above the older
  // stair-top placement.
  const STAR_GATE_W = 560;
  const STAR_GATE_H = STAR_GATE_W * (1024 / 1536);
  const STAR_GATE_X = GATE_CENTER_X - STAR_GATE_W / 2;
  const STAR_GATE_Y = STAIR_TOP_Y - STAR_GATE_H - GATE_LIFT;

  const INNER_LIGHT_W = 190;
  const INNER_LIGHT_H = INNER_LIGHT_W * (1535 / 1024);
  const INNER_LIGHT_X = GATE_CENTER_X - INNER_LIGHT_W / 2;
  const INNER_LIGHT_Y = STAIR_TOP_Y - INNER_LIGHT_H - GATE_LIFT;

  function placeObject(selector, x, y, width, height) {
    const node = document.querySelector(selector);
    if (!node) return;
    node.dataset.worldX = String(x);
    node.dataset.worldY = String(y);
    node.dataset.worldW = String(width);
    node.dataset.worldH = String(height);
  }

  placeObject(".scene-star-gate", STAR_GATE_X, STAR_GATE_Y, STAR_GATE_W, STAR_GATE_H);
  placeObject(".scene-gate-inner-light", INNER_LIGHT_X, INNER_LIGHT_Y, INNER_LIGHT_W, INNER_LIGHT_H);
  placeObject(".scene-gate-particle", GATE_CENTER_X - 210, STAIR_TOP_Y - 320 - GATE_LIFT, 420, 320);
  placeObject(".scene-gate-event", GATE_CENTER_X - 240, STAIR_TOP_Y - 350 - GATE_LIFT, 480, 350);

  const gateBase = document.querySelector(".scene-gate-base");
  if (gateBase) gateBase.hidden = true;

  layout.gateAssembly = Object.freeze({
    centerX: GATE_CENTER_X,
    baseline: STAIR_TOP_Y,
    lift: GATE_LIFT,
    starGate: Object.freeze({ x: STAR_GATE_X, y: STAR_GATE_Y, w: STAR_GATE_W, h: STAR_GATE_H }),
    innerLight: Object.freeze({ x: INNER_LIGHT_X, y: INNER_LIGHT_Y, w: INNER_LIGHT_W, h: INNER_LIGHT_H }),
    version: "native-foreground-v6",
  });

  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  function hasNearbySolid(shape) {
    if (shape.type !== "ellipse") return false;
    return (layout.solidBases || []).some((item) =>
      item.type === "ellipse" &&
      Math.abs(item.cx - shape.cx) < 3 &&
      Math.abs(item.cy - shape.cy) < 3,
    );
  }

  for (const area of layout.occluders || []) {
    if (!/(post|pillar)$/.test(area.id)) continue;
    const [x, , w] = area.bounds;
    const solid = {
      type: "ellipse",
      cx: x + w / 2,
      cy: area.baseline - 4,
      rx: clamp(w * 0.24, 12, 20),
      ry: 10,
      depthFix: area.id,
    };
    if (!hasNearbySolid(solid)) layout.solidBases.push(solid);
  }

  const depthZones = [
    ["east-upper-structure", 867, 217, 1215, 470],
    ["east-mid-structure", 873, 508, 1214, 697],
    ["west-upper-structure", 502, 401, 727, 460],
    ["west-mid-structure", 471, 461, 729, 698],
    ["west-gate-side", 568, 388, 614, 461],
    ["west-gate-approach", 605, 214, 775, 451],
    ["east-gate-approach", 866, 211, 932, 412],
    ["east-gate-side", 988, 367, 1082, 461],
  ];
  const existingIds = new Set((layout.occluders || []).map((area) => area.id));
  for (const [id, minX, minY, maxX, maxY] of depthZones) {
    const fullId = `depth-${id}`;
    if (existingIds.has(fullId)) continue;
    const visualLeft = Math.max(0, minX - 18);
    const visualTop = Math.max(0, minY - 190);
    const visualRight = Math.min(REFERENCE.width, maxX + 18);
